const before={'overlap-change':'baseline','repair-side':'bad','repair-up':'sideways','repack-B':'repaired','repack-C':'moveB','repack-D':'moveC','space-D':'repacked','space-E':'lifted'};
const focus={'scope':['A'],'baseline-read':[],'overlap-predict':['A','D'],'overlap-change':['A','D'],'overlap-area':['A','D'],'repair-side':['B','D'],'repair-up':['B','D'],'repair-score':['D'],'repack-B':['A','B'],'repack-C':['B','C'],'repack-D':['C','D'],'bottle-edge':['A','E'],'space-D':['D'],'space-E':['E'],'proof-witness':[]};
export const SCENES=DATA.scenes.map(s=>({...s,title:language==='en'?(typeof s.title==='object'?s.title.en:s.title):titles[s.key],caption:s.say[language],note:language==='en'?s.note:s.say.zh,to:clone(s.pack),from:clone(before[s.key]?DATA.states[before[s.key]]:s.pack),camera:s.key==='overlap-area'?CLOSE:['overlap-change','repair-side','repair-up'].includes(s.key)?NEAR:PACK,focus:focus[s.key]||[],illustration:['grid','contract','contract-bound','factors','contact','swap-space','metrics','lower-bound','prime','exclude','limits','transfer'].includes(s.view)||['grid','space-path'].includes(s.key)}));
for(const s of SCENES){if(s.motionStart!=null)continue;const first=s.wordCues?.[0],last=s.wordCues?.at(-1);s.motionStart=first?first.start-s.start:.65;s.motionEnd=last?Math.min(last.end-s.start,s.motionStart+2.6):3.25;s.anchorType=first?'measured-word':'authored';}
export const DURATION=DATA.duration;
// Visual copy can be refined without changing captions that match the existing audio.
const chapterNames=['为什么形状与摆放要一起优化','A变形以后，布局会怎样','先选出能用的形状','哪里发生了碰撞','移开以后，还要检查谁','怎样把周围几块摆紧','给E找一个更靠里的位置','换个指标看看结果','24还能不能更小','多软模块：形状前沿与联合优化','换个条件，再试一次'];
for(const s of SCENES){if(language==='zh'){s.title=COPY[s.key]?.title||s.title;s.note=COPY[s.key]?.note||s.note;}s.chapter={...s.chapter,zh:chapterNames[s.chapterIndex-1]};}
const mix=(a,b,p)=>a+(b-a)*p;export const ease=x=>{x=Math.max(0,Math.min(1,x));return x*x*(3-2*x);};
export function sceneAt(t){return SCENES.find(s=>t>=s.start&&t<s.end)||SCENES.at(-1);}
export function frameAt(t,reduced=false){const scene=sceneAt(Math.max(0,Math.min(DURATION,t))),i=SCENES.indexOf(scene),p=reduced?1:ease((t-scene.start-(scene.motionStart??.65))/((scene.motionEnd??3.75)-(scene.motionStart??.65))),camP=reduced?1:ease((t-scene.start)/1.3),previous=SCENES[Math.max(0,i-1)].camera,pack=clone(scene.from);for(const id of Object.keys(pack))for(const k of ['x','y','w','h'])pack[id][k]=mix(scene.from[id][k],scene.to[id][k],p);if(scene.key==='overlap-change')pack.A.h=6/pack.A.w;const moving=JSON.stringify(scene.from)!==JSON.stringify(scene.to)&&p<1;return{scene,pack,moving,illustration:scene.illustration,camera:scene.camera.map((x,j)=>mix(previous[j],x,camP)),report:moving||scene.illustration?null:check(pack)};}
export function check(pack){return inspect(pack,OUTLINE,MODULES,{soft:true,rotate:false});}
export function overlaps(pack){const result=[],ids=Object.keys(pack);for(let i=0;i<ids.length;i++)for(let j=i+1;j<ids.length;j++){const a=pack[ids[i]],b=pack[ids[j]],x=Math.max(a.x,b.x),y=Math.max(a.y,b.y),w=Math.min(a.x+a.w,b.x+b.w)-x,h=Math.min(a.y+a.h,b.y+b.h)-y;if(w>1e-8&&h>1e-8)result.push({ids:[ids[i],ids[j]],x,y,w,h,area:w*h});}return result;}
export function newSession(){return{time:0,trial:null,savedTime:null,base:null,selected:'A',history:[]};}
export function enterTrial(s,id){if(!s.trial){s.savedTime=s.time;s.base=clone(sceneAt(s.time).to);s.trial=clone(s.base);s.history=[];}s.selected=id;return s;}
export function leaveTrial(s){s.time=s.savedTime??s.time;s.trial=null;s.savedTime=null;s.base=null;s.history=[];return s;}
export function seek(s,t){s.trial=null;s.savedTime=null;s.base=null;s.history=[];s.time=Math.max(0,Math.min(DURATION,t));return s;}
export function edit(s,change){if(!s.trial)return;s.history.push(clone(s.trial));change(s.trial);}
